insert into public.projects (slug, status, sort_order, cover_url, cover_alt, title, summary, location, period, context, problem, objectives, beneficiaries, activities, results, partners, gallery) values ('vaccination-des-vidangeurs', 'done', 0, '/__l5e/assets-v1/898efcb3-cf65-4181-9cc5-b16f4f8a82b6/vidange-truck.jpg', '{"fr":"Camion de vidange en opération sur un site de dépotage à Nouakchott","ar":"شاحنة تفريغ أثناء العمل في موقع تفريغ بنواكشوط","en":"Emptying truck in operation at a discharge site in Nouakchott"}'::jsonb, '{"fr":"Vaccination des vidangeurs","ar":"تلقيح عمال التفريغ","en":"Vaccination of sanitation workers"}'::jsonb, '{"fr":"Campagne de vaccination et de protection sanitaire destinée aux travailleurs de la vidange, conduite avec les autorités sanitaires.","ar":"حملة تلقيح وحماية صحية لفائدة عمال التفريغ، أُنجزت بالتنسيق مع السلطات الصحية.","en":"A vaccination and health-protection campaign for emptying workers, run with the health authorities."}'::jsonb, '{"fr":"Nouakchott, Mauritanie","ar":"نواكشوط، موريتانيا","en":"Nouakchott, Mauritania"}'::jsonb, '{"fr":"2024","ar":"2024","en":"2024"}'::jsonb, '{"fr":"Les vidangeurs manipulent quotidiennement des boues fécales sans couverture vaccinale systématique ni équipement adapté.","ar":"يتعامل عمال التفريغ يومياً مع حمأة الصرف دون تغطية تلقيحية منهجية ولا تجهيزات ملائمة.","en":"Emptying workers handle faecal sludge daily, without systematic vaccination coverage or suitable equipment."}'::jsonb, '{"fr":"Une exposition élevée aux hépatites, au tétanos et aux infections gastro-intestinales, avec des arrêts de travail fréquents.","ar":"تعرض مرتفع للالتهاب الكبدي والكزاز والأمراض المعوية، مع توقفات متكررة عن العمل.","en":"High exposure to hepatitis, tetanus and gastro-intestinal infections, leading to frequent work stoppages."}'::jsonb, '{"fr":["Vacciner les travailleurs recensés","Distribuer des équipements de protection individuelle","Créer un registre sanitaire de suivi"],"ar":["تلقيح العاملين المسجلين","توزيع وسائل الحماية الفردية","إنشاء سجل صحي للمتابعة"],"en":["Vaccinate registered workers","Distribute personal protective equipment","Create a health follow-up registry"]}'::jsonb, '{"fr":"350 vidangeurs et leurs familles","ar":"350 عامل تفريغ وأسرهم","en":"350 emptying workers and their families"}'::jsonb, '{"fr":["Recensement des travailleurs","Séances de vaccination","Ateliers d''hygiène et de sécurité"],"ar":["إحصاء العاملين","جلسات التلقيح","ورشات النظافة والسلامة"],"en":["Worker census","Vaccination sessions","Hygiene and safety workshops"]}'::jsonb, '{"fr":"Une couverture vaccinale nettement améliorée, des équipements de protection distribués et une baisse des arrêts de travail signalés par les opérateurs.","ar":"تحسن واضح في التغطية التلقيحية، وتوزيع وسائل الحماية، وانخفاض التوقفات عن العمل التي أبلغ عنها المشغلون.","en":"Markedly improved vaccination coverage, protective equipment distributed, and fewer work stoppages reported by operators."}'::jsonb, '{"fr":"Autorités sanitaires nationales, commune d''intervention et opérateurs privés de vidange","ar":"السلطات الصحية الوطنية، بلدية التدخل، ومشغلو التفريغ الخاصون","en":"National health authorities, the host municipality and private emptying operators"}'::jsonb, '[{"src":"/__l5e/assets-v1/898efcb3-cf65-4181-9cc5-b16f4f8a82b6/vidange-truck.jpg","alt":{"fr":"Agents équipés lors d''une opération de vidange sur site de dépotage","ar":"أعوان مجهزون أثناء عملية تفريغ في موقع مخصص","en":"Equipped workers during an emptying operation at a discharge site"}},{"src":"/__l5e/assets-v1/30dc642e-50a5-410e-9ae6-49c1b5f3e4ed/clean-water-hands.jpg","alt":{"fr":"Démonstration de lavage des mains lors d''un atelier d''hygiène","ar":"عرض لغسل الأيدي خلال ورشة نظافة","en":"Handwashing demonstration during a hygiene workshop"}}]'::jsonb);
insert into public.projects (slug, status, sort_order, cover_url, cover_alt, title, summary, location, period, context, problem, objectives, beneficiaries, activities, results, partners, gallery) values ('gestion-des-dechets-littoral', 'upcoming', 1, '/__l5e/assets-v1/80334f01-e553-4c82-8b3d-972e420f748a/beach-waste.jpg', '{"fr":"Littoral mauritanien couvert de bidons et de déchets plastiques","ar":"ساحل موريتاني مغطى بالبراميل والنفايات البلاستيكية","en":"Mauritanian coastline covered with containers and plastic waste"}'::jsonb, '{"fr":"Gestion des déchets du littoral","ar":"تدبير نفايات الشريط الساحلي","en":"Coastal waste management"}'::jsonb, '{"fr":"Nettoyage participatif des plages et mise en place d''une filière de tri avec les communautés de pêcheurs.","ar":"تنظيف تشاركي للشواطئ وإرساء سلسلة فرز بمشاركة مجتمعات الصيادين.","en":"Participatory beach clean-ups and a waste sorting stream set up with fishing communities."}'::jsonb, '{"fr":"Zone côtière, Mauritanie","ar":"المنطقة الساحلية، موريتانيا","en":"Coastal zone, Mauritania"}'::jsonb, '{"fr":"2026","ar":"2026","en":"2026"}'::jsonb, '{"fr":"L''accumulation de déchets solides sur les plages et les sites de débarquement dégrade le cadre de vie et l''activité de pêche.","ar":"يؤدي تراكم النفايات الصلبة على الشواطئ ومواقع الإنزال إلى تدهور محيط الحياة ونشاط الصيد.","en":"Solid waste piling up on beaches and landing sites degrades living conditions and fishing activity."}'::jsonb, '{"fr":"Risques sanitaires pour les riverains et dégradation des ressources halieutiques.","ar":"مخاطر صحية على السكان المجاورين وتدهور الموارد السمكية.","en":"Health risks for nearby residents and degradation of fishery resources."}'::jsonb, '{"fr":["Organiser des campagnes de collecte","Installer des points de tri","Former des comités locaux de suivi"],"ar":["تنظيم حملات جمع","تركيب نقاط فرز","تكوين لجان محلية للمتابعة"],"en":["Run collection campaigns","Install sorting points","Train local monitoring committees"]}'::jsonb, '{"fr":"Communautés de pêcheurs, riverains et usagers du littoral","ar":"مجتمعات الصيادين والسكان المجاورون ومستخدمو الساحل","en":"Fishing communities, nearby residents and coastal users"}'::jsonb, '{"fr":["Cartographie des dépôts sauvages","Journées de nettoyage","Éducation environnementale"],"ar":["رسم خريطة نقاط التراكم العشوائي","أيام تنظيف","تربية بيئية"],"en":["Mapping of illegal dumps","Clean-up days","Environmental education"]}'::jsonb, '{"fr":"Objectif visé : des sites de débarquement assainis et un dispositif de tri géré durablement par les comités locaux.","ar":"الهدف المنشود: مواقع إنزال نظيفة ومنظومة فرز يديرها بشكل مستدام اللجان المحلية.","en":"Target outcome: clean landing sites and a sorting system sustainably managed by local committees."}'::jsonb, '{"fr":"Collectivités côtières, coopératives de pêche et services de l''environnement","ar":"الجماعات الساحلية، تعاونيات الصيد، ومصالح البيئة","en":"Coastal authorities, fishing cooperatives and environmental services"}'::jsonb, '[{"src":"/__l5e/assets-v1/80334f01-e553-4c82-8b3d-972e420f748a/beach-waste.jpg","alt":{"fr":"Plage jonchée de bidons plastiques avant campagne de nettoyage","ar":"شاطئ مغطى ببراميل بلاستيكية قبل حملة التنظيف","en":"Beach littered with plastic containers before a clean-up campaign"}}]'::jsonb);
insert into public.projects (slug, status, sort_order, cover_url, cover_alt, title, summary, location, period, context, problem, objectives, beneficiaries, activities, results, partners, gallery) values ('acces-eau-potable', 'upcoming', 2, '/__l5e/assets-v1/30dc642e-50a5-410e-9ae6-49c1b5f3e4ed/clean-water-hands.jpg', '{"fr":"Mains remplissant un bidon à un point d''eau potable","ar":"أيدٍ تملأ برميلاً من نقطة ماء صالح للشرب","en":"Hands filling a container at a safe water point"}'::jsonb, '{"fr":"Accès à l''eau potable et hygiène","ar":"الولوج إلى الماء الصالح للشرب والنظافة","en":"Safe water access and hygiene"}'::jsonb, '{"fr":"Points d''eau, stations de lavage des mains et éducation à l''hygiène dans les écoles des quartiers périurbains.","ar":"نقاط ماء ومحطات لغسل الأيدي وتربية على النظافة في مدارس الأحياء شبه الحضرية.","en":"Water points, handwashing stations and hygiene education in peri-urban schools."}'::jsonb, '{"fr":"Quartiers périurbains de Nouakchott","ar":"أحياء شبه حضرية بنواكشوط","en":"Peri-urban districts of Nouakchott"}'::jsonb, '{"fr":"2026–2027","ar":"2026–2027","en":"2026–2027"}'::jsonb, '{"fr":"Plusieurs quartiers en forte croissance disposent d''un accès limité à l''eau potable et d''installations sanitaires insuffisantes.","ar":"تعاني عدة أحياء سريعة النمو من ولوج محدود للماء الصالح للشرب ومن نقص في التجهيزات الصحية.","en":"Several fast-growing districts have limited access to safe water and insufficient sanitation facilities."}'::jsonb, '{"fr":"Maladies hydriques récurrentes chez les enfants et absentéisme scolaire associé.","ar":"أمراض مرتبطة بالماء متكررة لدى الأطفال وغياب مدرسي مرتبط بها.","en":"Recurrent waterborne diseases among children and related school absenteeism."}'::jsonb, '{"fr":["Équiper les écoles en points d''eau","Former des clubs d''hygiène","Suivre la qualité de l''eau"],"ar":["تجهيز المدارس بنقاط ماء","تكوين نوادي النظافة","متابعة جودة الماء"],"en":["Equip schools with water points","Set up hygiene clubs","Monitor water quality"]}'::jsonb, '{"fr":"Élèves, enseignants et familles des quartiers ciblés","ar":"التلاميذ والمدرسون وأسر الأحياء المستهدفة","en":"Pupils, teachers and families in the target districts"}'::jsonb, '{"fr":["Installation d''équipements","Sessions pédagogiques","Analyses périodiques de l''eau"],"ar":["تركيب التجهيزات","حصص بيداغوجية","تحاليل دورية للماء"],"en":["Equipment installation","Teaching sessions","Periodic water testing"]}'::jsonb, '{"fr":"Objectif visé : des écoles équipées durablement et une baisse des maladies hydriques déclarées.","ar":"الهدف المنشود: مدارس مجهزة بشكل مستدام وانخفاض في الأمراض المرتبطة بالماء.","en":"Target outcome: sustainably equipped schools and a decline in reported waterborne illness."}'::jsonb, '{"fr":"Directions régionales de l''éducation, services d''hydraulique et associations de parents d''élèves","ar":"المديريات الجهوية للتعليم، مصالح الهيدروليك، وجمعيات أولياء التلاميذ","en":"Regional education directorates, water services and parent-teacher associations"}'::jsonb, '[{"src":"/__l5e/assets-v1/30dc642e-50a5-410e-9ae6-49c1b5f3e4ed/clean-water-hands.jpg","alt":{"fr":"Point d''eau communautaire utilisé par les habitants du quartier","ar":"نقطة ماء جماعية يستخدمها سكان الحي","en":"Community water point used by neighbourhood residents"}}]'::jsonb);
insert into public.projects (slug, status, sort_order, cover_url, cover_alt, title, summary, location, period, context, problem, objectives, beneficiaries, activities, results, partners, gallery) values ('preservation-des-oasis', 'upcoming', 3, '/__l5e/assets-v1/aae8c064-1858-4b4a-9f89-9ac91068e69e/oasis.jpg', '{"fr":"Oasis mauritanienne : palmeraie et plan d''eau en bordure de dunes","ar":"واحة موريتانية: نخيل ومسطح مائي على حدود الكثبان","en":"Mauritanian oasis: palm grove and water body at the edge of the dunes"}'::jsonb, '{"fr":"Préservation des oasis","ar":"الحفاظ على الواحات","en":"Oasis preservation"}'::jsonb, '{"fr":"Protection des ressources en eau et promotion d''un assainissement écologique en milieu oasien.","ar":"حماية الموارد المائية وتعزيز الإصحاح الإيكولوجي في الواحات.","en":"Protecting water resources and promoting ecological sanitation in oasis areas."}'::jsonb, '{"fr":"Régions oasiennes, Mauritanie","ar":"مناطق الواحات، موريتانيا","en":"Oasis regions, Mauritania"}'::jsonb, '{"fr":"2027","ar":"2027","en":"2027"}'::jsonb, '{"fr":"La pression sur les nappes et les palmeraies s''accentue, alors que les eaux usées sont rarement traitées.","ar":"يتزايد الضغط على المياه الجوفية وواحات النخيل، في حين تبقى المياه العادمة نادراً ما تُعالج.","en":"Pressure on aquifers and palm groves is increasing while wastewater is rarely treated."}'::jsonb, '{"fr":"Pollution diffuse des points d''eau et gestion insuffisante des eaux usées domestiques.","ar":"تلوث منتشر لنقاط الماء وتدبير غير كافٍ للمياه العادمة المنزلية.","en":"Diffuse pollution of water points and inadequate management of domestic wastewater."}'::jsonb, '{"fr":["Protéger les points d''eau","Promouvoir l''assainissement écologique","Impliquer les coopératives agricoles"],"ar":["حماية نقاط الماء","تعزيز الإصحاح الإيكولوجي","إشراك التعاونيات الزراعية"],"en":["Protect water points","Promote ecological sanitation","Involve farming cooperatives"]}'::jsonb, '{"fr":"Populations oasiennes, agriculteurs et coopératives","ar":"سكان الواحات والمزارعون والتعاونيات","en":"Oasis populations, farmers and cooperatives"}'::jsonb, '{"fr":["Études hydrologiques","Démonstrations techniques","Formation des coopératives"],"ar":["دراسات هيدرولوجية","عروض تقنية","تكوين التعاونيات"],"en":["Hydrological studies","Technical demonstrations","Cooperative training"]}'::jsonb, '{"fr":"Objectif visé : des points d''eau protégés et des dispositifs d''assainissement écologique répliqués par les coopératives.","ar":"الهدف المنشود: نقاط ماء محمية ومنظومات إصحاح إيكولوجي تعيد التعاونيات تطبيقها.","en":"Target outcome: protected water points and ecological sanitation systems replicated by cooperatives."}'::jsonb, '{"fr":"Coopératives oasiennes, services de l''hydraulique et institutions de recherche","ar":"تعاونيات الواحات، مصالح الهيدروليك، ومؤسسات البحث","en":"Oasis cooperatives, water services and research institutions"}'::jsonb, '[{"src":"/__l5e/assets-v1/aae8c064-1858-4b4a-9f89-9ac91068e69e/oasis.jpg","alt":{"fr":"Palmeraie et plan d''eau à préserver en zone oasienne","ar":"نخيل ومسطح مائي يستحقان الحماية في منطقة واحات","en":"Palm grove and water body to be preserved in an oasis area"}}]'::jsonb);
insert into public.projects (slug, status, sort_order, cover_url, cover_alt, title, summary, location, period, context, problem, objectives, beneficiaries, activities, results, partners, gallery) values ('traitement-boues-vidange', 'upcoming', 4, '/__l5e/assets-v1/c14a7dda-61a1-47f6-8ba2-6b083feef03f/traitement-boues-vidange.jpg', '{"fr":"Vue aérienne d''un site de traitement des boues de vidange : bassins et lits de séchage","ar":"منظر جوي لموقع معالجة حمأة الصرف: أحواض وأسرّة تجفيف","en":"Aerial view of a faecal sludge treatment site: ponds and drying beds"}'::jsonb, '{"fr":"Traitement des boues de vidange","ar":"معالجة حمأة الصرف","en":"Faecal sludge treatment"}'::jsonb, '{"fr":"Appui à la mise en place et au suivi de sites de traitement des boues de vidange : bassins, lits de séchage et contrôle qualité.","ar":"دعم إنشاء ومتابعة مواقع معالجة حمأة الصرف: الأحواض، أسرّة التجفيف، ومراقبة الجودة.","en":"Support for the development and monitoring of faecal sludge treatment sites: ponds, drying beds and quality control."}'::jsonb, '{"fr":"Nouakchott et communes périphériques, Mauritanie","ar":"نواكشوط والبلديات المجاورة، موريتانيا","en":"Nouakchott and surrounding municipalities, Mauritania"}'::jsonb, '{"fr":"2026–2027","ar":"2026–2027","en":"2026–2027"}'::jsonb, '{"fr":"Les boues collectées par les opérateurs de vidange sont trop souvent déversées sans traitement, au détriment de la santé publique et de l''environnement.","ar":"تُلقى الحمأة التي يجمعها مشغلو التفريغ غالباً دون معالجة، مما يضر بالصحة العامة والبيئة.","en":"Sludge collected by emptying operators is too often discharged untreated, harming public health and the environment."}'::jsonb, '{"fr":"Absence d''infrastructures de traitement adaptées, risques de contamination des nappes et nuisances pour les populations riveraines.","ar":"غياب منشآت معالجة ملائمة، ومخاطر تلوث المياه الجوفية، وإزعاج للسكان المجاورين.","en":"Lack of suitable treatment infrastructure, risk of groundwater contamination and nuisance for nearby residents."}'::jsonb, '{"fr":["Sécuriser les sites de dépotage et de traitement","Suivre la qualité des boues traitées et des rejets","Former les gestionnaires des installations"],"ar":["تأمين مواقع التفريغ والمعالجة","متابعة جودة الحمأة المعالجة والمياه المصروفة","تكوين مدبّري المنشآت"],"en":["Secure discharge and treatment sites","Monitor the quality of treated sludge and effluents","Train facility managers"]}'::jsonb, '{"fr":"Populations riveraines, opérateurs de vidange et collectivités","ar":"السكان المجاورون ومشغلو التفريغ والجماعات المحلية","en":"Nearby residents, emptying operators and local authorities"}'::jsonb, '{"fr":["Diagnostic des sites existants","Appui technique au dimensionnement des bassins et lits de séchage","Mise en place d''un protocole de contrôle qualité"],"ar":["تشخيص المواقع القائمة","دعم تقني لتحديد أبعاد الأحواض وأسرّة التجفيف","وضع بروتوكول لمراقبة الجودة"],"en":["Assessment of existing sites","Technical support for pond and drying-bed sizing","Introduction of a quality-control protocol"]}'::jsonb, '{"fr":"Objectif visé : des sites de traitement opérationnels, contrôlés et intégrés à la filière d''assainissement de Nouakchott.","ar":"الهدف المنشود: مواقع معالجة جاهزة للعمل وخاضعة للمراقبة ومدمجة في سلسلة الإصحاح بنواكشوط.","en":"Target outcome: operational, monitored treatment sites integrated into Nouakchott''s sanitation chain."}'::jsonb, '{"fr":"Services techniques de l''assainissement, communes concernées et opérateurs privés de vidange","ar":"المصالح التقنية للإصحاح، البلديات المعنية، ومشغلو التفريغ الخاصون","en":"Sanitation technical services, the municipalities concerned and private emptying operators"}'::jsonb, '[{"src":"/__l5e/assets-v1/c14a7dda-61a1-47f6-8ba2-6b083feef03f/traitement-boues-vidange.jpg","alt":{"fr":"Bassins et lits de séchage d''un site de traitement des boues de vidange","ar":"أحواض وأسرّة تجفيف في موقع لمعالجة حمأة الصرف","en":"Ponds and drying beds at a faecal sludge treatment site"}}]'::jsonb);
insert into public.news (slug, category, published_on, cover_url, title, excerpt, body) values ('campagne-vaccination-cloturee', 'terrain', '2026-06-12', '/__l5e/assets-v1/898efcb3-cf65-4181-9cc5-b16f4f8a82b6/vidange-truck.jpg', '{"fr":"Clôture de la campagne de vaccination des vidangeurs","ar":"ختام حملة تلقيح عمال التفريغ","en":"Vaccination campaign for sanitation workers concludes"}'::jsonb, '{"fr":"Bilan de la campagne menée avec les autorités sanitaires auprès des travailleurs de la vidange.","ar":"حصيلة الحملة المنجزة مع السلطات الصحية لفائدة عمال التفريغ.","en":"Results of the campaign conducted with the health authorities for emptying workers."}'::jsonb, '{"fr":["La campagne de vaccination des travailleurs de la vidange s''est déroulée sur plusieurs semaines dans les quartiers d''intervention de l''AMAA, en coordination avec les autorités sanitaires et les communes concernées.","Les équipes ont associé trois volets complémentaires : la vaccination des agents recensés, la distribution d''équipements de protection individuelle et des ateliers pratiques sur les gestes d''hygiène et la sécurité au travail.","Les opérateurs partenaires signalent une baisse des arrêts de travail liés aux infections. Un registre sanitaire a été mis en place afin d''assurer le suivi des rappels vaccinaux."],"ar":["استمرت حملة تلقيح عمال التفريغ عدة أسابيع في أحياء تدخل الجمعية، بالتنسيق مع السلطات الصحية والبلديات المعنية.","جمعت الفرق ثلاثة محاور متكاملة: تلقيح الأعوان المسجلين، وتوزيع وسائل الحماية الفردية، وورشات تطبيقية حول ممارسات النظافة والسلامة المهنية.","يسجل المشغلون الشركاء انخفاضاً في التوقفات عن العمل المرتبطة بالإصابات. وقد أُنشئ سجل صحي لضمان متابعة الجرعات التذكيرية."],"en":["The vaccination campaign for emptying workers ran over several weeks in AMAA''s intervention districts, in coordination with the health authorities and the municipalities involved.","Teams combined three complementary components: vaccination of registered workers, distribution of personal protective equipment, and practical workshops on hygiene and occupational safety.","Partner operators report fewer infection-related work stoppages. A health registry was set up to track booster doses."]}'::jsonb);
insert into public.news (slug, category, published_on, cover_url, title, excerpt, body) values ('nouveau-partenariat-institutionnel', 'institutionnel', '2026-04-03', '/__l5e/assets-v1/aae8c064-1858-4b4a-9f89-9ac91068e69e/oasis.jpg', '{"fr":"Nouveau partenariat institutionnel pour l''assainissement","ar":"شراكة مؤسسية جديدة من أجل الإصحاح","en":"New institutional partnership for sanitation"}'::jsonb, '{"fr":"Signature d''une convention de coopération technique portant sur la gestion des boues de vidange.","ar":"التوقيع على اتفاقية تعاون تقني تتعلق بتدبير حمأة الصرف.","en":"A technical cooperation agreement on faecal sludge management has been signed."}'::jsonb, '{"fr":["L''AMAA a signé une convention de coopération technique visant à renforcer la gestion des boues de vidange dans les zones urbaines à forte densité.","La convention prévoit un appui au diagnostic des sites de dépotage, un accompagnement des opérateurs privés et la production de données de terrain utiles aux décisions publiques.","Les premières activités conjointes portent sur la cartographie des flux de boues et sur la formation des agents municipaux chargés du contrôle."],"ar":["وقّعت الجمعية الموريتانية للإصحاح اتفاقية تعاون تقني تهدف إلى تعزيز تدبير حمأة الصرف في المناطق الحضرية الكثيفة السكان.","تنص الاتفاقية على دعم تشخيص مواقع التفريغ، ومواكبة المشغلين الخاصين، وإنتاج بيانات ميدانية تفيد القرار العمومي.","تتعلق الأنشطة المشتركة الأولى برسم خريطة تدفقات الحمأة وبتكوين أعوان البلديات المكلفين بالمراقبة."],"en":["AMAA has signed a technical cooperation agreement to strengthen faecal sludge management in densely populated urban areas.","The agreement provides for support in assessing discharge sites, assistance to private operators, and the production of field data to inform public decisions.","The first joint activities focus on mapping sludge flows and training municipal agents responsible for oversight."]}'::jsonb);
insert into public.news (slug, category, published_on, cover_url, title, excerpt, body) values ('session-formation-vidangeurs', 'formation', '2026-02-18', '/__l5e/assets-v1/30dc642e-50a5-410e-9ae6-49c1b5f3e4ed/clean-water-hands.jpg', '{"fr":"Session de formation pour les opérateurs de vidange","ar":"دورة تكوينية لفائدة عمال التفريغ","en":"Training session for emptying operators"}'::jsonb, '{"fr":"Trois jours de modules pratiques consacrés à la sécurité au travail et à la prévention des risques.","ar":"ثلاثة أيام من الوحدات التطبيقية حول السلامة المهنية والوقاية من المخاطر.","en":"Three days of practical modules on occupational safety and risk prevention."}'::jsonb, '{"fr":["L''AMAA a organisé une session de formation de trois jours réunissant des opérateurs de vidange et des agents municipaux.","Les modules ont porté sur le port des équipements de protection, la manipulation des boues, la prévention des accidents et les gestes de premiers secours.","Chaque participant a reçu un support pédagogique trilingue. Les formateurs issus de la session assureront la démultiplication auprès de leurs équipes."],"ar":["نظمت الجمعية دورة تكوينية على مدى ثلاثة أيام جمعت مشغلي التفريغ وأعوان البلديات.","تناولت الوحدات استخدام وسائل الحماية، والتعامل مع الحمأة، والوقاية من الحوادث، وإسعافات أولية.","تلقى كل مشارك حافظة بيداغوجية بثلاث لغات، وسيتولى المكوّنون المتخرجون من الدورة نقل المكتسبات إلى فرقهم."],"en":["AMAA held a three-day training session bringing together emptying operators and municipal agents.","Modules covered the use of protective equipment, sludge handling, accident prevention and first aid.","Each participant received trilingual teaching material, and the trainers certified in the session will pass on the content to their own teams."]}'::jsonb);
